#region Usings
using SF.CodeGeneration;
using Xunit;
#endregion

namespace SF.CSharpWriter.Tests;

/// <summary>
/// Preprocessor directives (always at the left margin) and the auto-generated header. Each test starts a new file
/// and checks the exact text.
/// </summary>
public sealed class PreprocessorTests
{
    [Fact]
    public void AutoGeneratedHeader()
    {
        CSharpFile.Start(4);
        CSharpFile.AutoGeneratedHeader();

        Assert.Equal(Code.Lines("// <auto-generated/>"), CSharpFile.ToString());
    }

    [Fact]
    public void Symbols()
    {
        CSharpFile.Start(4);
        CSharpFile.Define("FEATURE");
        CSharpFile.Undefine("OTHER");

        Assert.Equal(Code.Lines("#define FEATURE", "#undef OTHER"), CSharpFile.ToString());
    }

    [Fact]
    public void ConditionalCompilation()
    {
        CSharpFile.Start(4);
        CSharpFile.IfDirective("DEBUG");
        CSharpFile.ElifDirective("NET10_0_OR_GREATER && !BROWSER");
        CSharpFile.ElseDirective();
        CSharpFile.EndIfDirective();

        Assert.Equal(Code.Lines("#if DEBUG", "#elif NET10_0_OR_GREATER && !BROWSER", "#else", "#endif"), CSharpFile.ToString());
    }

    [Theory]
    [InlineData("enable")]
    [InlineData("disable")]
    [InlineData("restore")]
    [InlineData("enable warnings")]
    public void Nullable(string setting)
    {
        CSharpFile.Start(4);
        CSharpFile.Nullable(setting);

        Assert.Equal(Code.Lines("#nullable " + setting), CSharpFile.ToString());
    }

    [Fact]
    public void PragmaWarnings()
    {
        CSharpFile.Start(4);
        CSharpFile.PragmaWarningDisable("CS0168, CS0219");
        CSharpFile.PragmaWarningRestore("CS0168, CS0219");

        Assert.Equal(Code.Lines("#pragma warning disable CS0168, CS0219", "#pragma warning restore CS0168, CS0219"), CSharpFile.ToString());
    }

    [Theory]
    [InlineData("")]
    [InlineData(null)]
    public void PragmaWarningsWithoutCodesCoverEveryWarning(string codes)
    {
        CSharpFile.Start(4);
        CSharpFile.PragmaWarningDisable(codes);
        CSharpFile.PragmaWarningRestore(codes);

        Assert.Equal(Code.Lines("#pragma warning disable", "#pragma warning restore"), CSharpFile.ToString());
    }

    [Fact]
    public void Messages()
    {
        CSharpFile.Start(4);
        CSharpFile.WarningDirective("Check this");
        CSharpFile.ErrorDirective("Not supported");
        CSharpFile.LineDirective("hidden");
        CSharpFile.LineDirective("default");

        Assert.Equal(Code.Lines("#warning Check this", "#error Not supported", "#line hidden", "#line default"), CSharpFile.ToString());
    }

    [Fact]
    public void DirectivesStayAtTheLeftMargin()
    {
        CSharpFile.Start(4);
        CSharpFile.OpenClass("public", "Settings");
        CSharpFile.IfDirective("DEBUG");
        CSharpFile.Const("public", "int", "Level", "1");
        CSharpFile.ElseDirective();
        CSharpFile.Const("public", "int", "Level", "0");
        CSharpFile.EndIfDirective();
        CSharpFile.PragmaWarningDisable("CS0414");
        CSharpFile.Nullable("enable");
        CSharpFile.CloseType();

        var expected = Code.Lines(
            "public class Settings",
            "{",
            "#if DEBUG",
            "    public const int Level = 1;",
            "#else",
            "    public const int Level = 0;",
            "#endif",
            "#pragma warning disable CS0414",
            "#nullable enable",
            "}");
        Assert.Equal(expected, CSharpFile.ToString());
    }
}
